pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.owner();
        vm.deal(address(this), 2 ether);
        vm.deal(address(c), 0);
        // fund the contract with 1 ether via go
        (bool ok, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("go()"));
        require(ok, "go call failed");
        // after go, reference contract transfers balance to owner; modified doesn't.
        // Check that the owner's balance increase equals the contract's balance.
        uint256 balanceBefore = owner.balance;
        // call go again from another account to trigger another transfer in reference
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        (bool ok2, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("go()"));
        require(ok2, "second go call failed");
        uint256 balanceAfter = owner.balance;
        // The reference version transfers contract balance after each go, so the increase equals the contract's balance.
        // The modified version never transfers, so the increase is 0.
        bool same = (balanceAfter - balanceBefore) == address(c).balance;
        assertTrue(same);
    }
}

