pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract directly (simulate fallback) to give it a prior balance
        vm.deal(address(c), 1 ether);
        // Actor sends 1 ether via go()
        vm.deal(address(this), 1 ether);
        // Call go() - note: the call will revert on buggy version due to require failure
        bool ok;
        try c.go{value: 1 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference version, go() succeeds and transfers all balance to owner;
        // In buggy version, go() reverts; so we assert ok is true
        assertTrue(ok);
    }
}

