pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // set up specific scenario: fund contract via go() with 1 ether
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        vm.deal(target, 1 ether);  // so target.call doesn't revert silently
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.go{value: 1 ether}();
        // reference: after go(), all balance (msg.value minus any sent to target? actually target.call forwards msg.value, then transfer owner balance) -> owner gets balance, contract ends with 0
        // buggy: transfer(0) -> contract retains full balance (1 ether minus forwarded? forwarded 1 ether to target, so contract balance is 0 after call? wait: msg.value=1 ether sent to target, target receives it, contract balance becomes 0 after call, then transfer(0) sends 0 to owner, so contract balance remains 0) actually both end with 0 balance because the forwarded value leaves contract empty. Need different scenario: fund contract before go() so it has extra balance.
        // Better: pre-fund contract with 2 ether, then call go() with 0 value so forwarded value=0, require passes if target can receive 0, then transfer sends remaining balance (3 ether? actually contract balance = 2 ether pre + 0 msg.value = 2 ether, reference sends 2 ether to owner, buggy sends 0, so contract retains 2 ether.
        vm.deal(address(c), 2 ether);
        vm.deal(target, 1 ether); // target must accept call
        vm.prank(address(this));
        c.go{value: 0}();
        // Now reference: contract balance after go() = 0 (transferred all to owner)
        // Buggy: contract balance after go() = 2 ether (transfer(0) didn't send)
        assertEq(address(c).balance, 0);
    }
}

